!function(){"use strict";var FrameDataSchema=null;if("undefined"!=typeof module&&module.exports){var path=require("path");try{FrameDataSchema=require(path.resolve(__dirname,"../../../shim/frame-data/index.js"))}catch(e){FrameDataSchema=null}}else FrameDataSchema="undefined"!=typeof window&&window.FrameDataSchema||null;var EngineScopeDescriptors={FrameDescriptor:{kind:"Frame",description:"Any simulation frame (leaf or composite). Provides writable access to engine-core properties via getFrameProperty/setFrameProperty. Leaf frames (is_leaf=true) are the fundamental quanta; composite frames are parent nodes in the Frame hierarchy. The Frame Axiom: everything is a Frame — there is no separate particle class. Position/velocity/mass writes bypass move() by design (user override); the engine's CA rules reconcile topology and wavelength on the next tick. Topology (parent/children) is engine-owned and FORBIDDEN from user writes.",fields:[{name:"x",type:"writable",engineVisible:!0,unit:"px",description:"Frame center X position (physics pixels). Write repositions the frame directly, bypassing move() — user override. The engine does not clamp; caller is responsible for placing within bounds. Children that escape their parent rect are released next tick by releaseEscapedChildren."},{name:"y",type:"writable",engineVisible:!0,description:"Frame center Y position (physics pixels). Write repositions the frame directly, bypassing move() — user override."},{name:"z",type:"writable",engineVisible:!0,description:"Frame center Z position (depth, physics pixels). Default 0.0 when active_axes.z is false (2D mode). Bite 3 (ws-3d-discrete-walk): set by the 3D emitter; moved by the independent z yo-yo coin when active_axes.z is true. Cube edge = w (spec §11 — no separate d field; cubes only)."},{name:"left",type:"writable",engineVisible:!0,description:"Frame left edge (physics pixels). Write repositions the frame by its left edge (mirrors lo._eject otherRect.left = newLeft). Bit-identical to the native WALL eject — used in §10.3 eject-expression programs. Setting left also updates right; center x is derived."},{name:"top",type:"writable",engineVisible:!0,description:"Frame top edge (physics pixels). Write repositions the frame by its top edge (mirrors lo._eject otherRect.top = newTop). Bit-identical to the native WALL eject — used in §10.3 eject-expression programs. Setting top also updates bottom; center y is derived."},{name:"vx",type:"writable",engineVisible:!0,unit:"px/tick",description:"X velocity / momentum (pixels/tick). Positive = rightward, negative = leftward. The 1px/tick speed limit still applies on the next move() call; excess accumulates back into vx."},{name:"vy",type:"writable",engineVisible:!0,description:"Y velocity / momentum (pixels/tick). Positive = downward (screen coords), negative = upward."},{name:"vz",type:"writable",engineVisible:!0,description:"Z velocity / momentum (pixels/tick). Default 0.0 when active_axes.z is false (2D mode). When active_axes.z is true, the yo-yo z coin adds/subtracts to vz each tick for the transverse axes (spec §3 / D5/D10). The Euclidean L2 walk probs include vz: D = sqrt(vx²+vy²+vz²)."},{name:"mass",type:"writable",engineVisible:!0,description:"Pixel occupancy count. Feeds setWavelength() on the next tick (EGPTfrqtl.js:1716 / FrameStore.set_wavelength). Higher mass → shorter wavelength → higher frequency (E=mc² analog, invariant 6)."},{name:"charge",type:"writable",engineVisible:!0,description:'Charge polarity: "POSITIVE" or "NEGATIVE" (canonical SCREAMING_SNAKE). Determines wave phase (sine vs cosine random walk) and bonding attraction/repulsion. Wire format: provider translates to engine-native (JS: 0/1; Rust: Charge enum).'},{name:"is_alive",type:"writable",engineVisible:!0,description:"Liveness flag. Setting false kills the frame: it is excluded from physics next tick and GC'd at end-of-tick. Equivalent to killFrame(id) but accessed uniformly. Children of a killed composite are orphaned (not recursively killed) — topology is reconciled by garbageCollectDeadParents."},{name:"is_stationary",type:"writable",engineVisible:!0,description:"Pins the frame in place: move() is skipped when true. Existing per-frame flag (EGPTfrqtl.js:1681 / FrameStore.is_stationary). Used in bespoke experiments to freeze specific frames while others evolve."},{name:"wrap",type:"writable",engineVisible:!0,description:"Toroidal boundary for this individual frame. When true the frame wraps at the canvas edges instead of escaping or bouncing. Overrides the universe-level wrap setting for this frame."},{name:"speed_prob",type:"writable",engineVisible:!0,description:'Per-frame OVERRIDE of the leaf longitudinal "speed probability" — the probability the frame takes its along-momentum step this tick (frame.rs move_frame leaf gate). Sentinel -1.0 (default; any negative resets to it) = derive from fullness (mass/capacity). When >= 0.0 it overrides the gate so user space can set the move-probability independent of mass — e.g. red vs blue light sharing a speed while differing in momentum/wavelength. Does NOT change the orthogonal wavelength.'},{name:"local_time",type:"writable",constraint:{integer:!0},engineVisible:!0,description:"Per-frame wave-phase counter (integer ticks; EGPTfrqtl.js:2473 / frame.rs local_time). Drives the spin/coin-flip via local_time % wavelength. Incremented each tick; reset to 0 on collision/reset. Op-programs that reproduce the native reset() (e.g. compiled RANDOM_* collision behavior) write 0 here. CANONICAL home for the writable-prop contract — both engines mirror this descriptor; neither hand-lists it (schema-mirror-drift fix)."},{name:"data",type:"writable",engineVisible:!0,dataBubbleSchema:FrameDataSchema,description:"The per-frame data bubble: { detection, render, ext }. Sub-shape is owned by lib/shim/frame-data (SECTION_KEYS + normalizeDataBubble). detection — written by engine MARK/DETECT primitives (detector_name). render    — written by sugar (emitter stamps data.render.color); renderer reads. ext       — developer-extensible; JS-only (not cross-engine assertable). NEVER enumerate the section keys here — always resolve from FrameDataSchema."},{name:"fullness",type:"readonly",engineVisible:!0,description:"Derived: mass / capacity (0.0–1.0). Used by the renderer for color mapping and by detectors for density measurement. Not directly writable — set mass to change fullness indirectly."},{name:"capacity",type:"readonly",engineVisible:!0,unit:"px²",description:"Derived: rect.w * rect.h (physics pixels). Fixed at frame creation; determined by the frame's bounding rect size."},{name:"child_count",type:"readonly",engineVisible:!0,description:"Number of direct children in this frame's hierarchy (0 for leaf frames). Per-tick result; changes as promote/merge/release rules run."},{name:"collided_id",type:"readonly",engineVisible:!0,description:"ID of the other frame this frame collided with in the last tick, or -1/null if no collision occurred. Per-tick result from the Phase C collide pass."},{name:"r",type:"readonly",engineVisible:!0,description:"Radius cache: max(rect.w, rect.h) / 2. Used in proximity checks and rendering. Derived from rect size."},{name:"w",type:"readonly",engineVisible:!0,description:"Frame width in physics pixels (fixed at creation, derived from rect.w). Read in op-program scope for eject geometry: set frame.left = self.left - frame.w - 1. For leaf quanta this is 1."},{name:"h",type:"readonly",engineVisible:!0,description:"Frame height in physics pixels (fixed at creation, derived from rect.h). Read in op-program scope for eject geometry: set frame.top = self.top - frame.h - 1. For leaf quanta this is 1."},{name:"layer",type:"readonly",engineVisible:!0,description:"Dimension layer membership (u32). Assigned at frame creation; engine-managed — changes only when the frame is promoted to a higher dimension. User writes are REJECTED (use the promote/detach structural primitives)."},{name:"prev_x",type:"readonly",engineVisible:!0,description:'Derived (scope-read): frame CENTER X before this tick\'s move() (physics pixels). Readable in op-program scope as Ref(0,"prev_x") — the compiled MOMENTUM_BASED behavior restores pre-move position via set 0.x = prev_x. Read-only — write THROWS (engine-owned per-tick snapshot, saved by Frame::move).'},{name:"prev_y",type:"readonly",engineVisible:!0,description:'Derived (scope-read): frame CENTER Y before this tick\'s move() (physics pixels). Readable in op-program scope as Ref(0,"prev_y"). Read-only — write THROWS (engine-owned per-tick snapshot, saved by Frame::move).'},{name:"prev_z",type:"readonly",engineVisible:!0,description:"Derived (scope-read): frame CENTER Z before this tick's move() (physics pixels). Default 0.0 when active_axes.z is false. Bite 3 (ws-3d-discrete-walk): saved by Frame::move_frame alongside prev_x/prev_y. Read-only — write THROWS (engine-owned per-tick snapshot)."},{name:"parent",type:"forbidden",engineVisible:!1,description:"FORBIDDEN — engine-owned topology. The parent link is managed exclusively by the engine's promote/detach/GC rules. Any write attempt FAIL-LOUDs with a TypeError. To move a frame: write its x/y position and let the engine reconcile topology (releaseEscapedChildren drops children outside their parent rect next tick)."},{name:"children",type:"forbidden",engineVisible:!1,description:"FORBIDDEN — engine-owned topology. The children list is managed exclusively by the engine's promote/attach/detach rules. Any write attempt FAIL-LOUDs with a TypeError."}]},UniverseDescriptor:{kind:"Universe",description:"The top-level simulation universe. Most properties are read-only state accessible from op-programs via HANDLE_UNIVERSE (2) in the expression scope; a small number of universe-wide physics constants (currently: wavelengthScale) are writable through the validated setUniverseProperty accessor. THROW-OR-APPLY: any write to an unknown or readonly field FAIL-LOUDs with TypeError — there is no bind-local property list anywhere in the stack.",fields:[{name:"tick",type:"readonly",engineVisible:!0,description:'Current tick count (u64). Increments once per doTick() call. Available in op-program scope via Ref(HANDLE_UNIVERSE, "tick"). Write THROWS — tick is engine-owned and monotonically increasing.'},{name:"activeQuanta",type:"readonly",engineVisible:!0,description:'Number of currently alive leaf quanta (usize). Derived by counting is_alive=true frames in the fundamental dimension. Available in op-program scope via Ref(HANDLE_UNIVERSE, "activeQuanta"). Write THROWS — this is a derived aggregate, not a writable property.'},{name:"wavelengthScale",type:"number",constraint:{min:1,integer:!0},widgetHint:"slider",widgetConfig:{max:32,step:1},engineVisible:!0,description:"Layer 1 — universe-wide oscillation-wavelength scale: `wavelength = floor((capacity/mass) * wavelengthScale)`, minimum 4 (Core Axioms §6B). Every Frame in the universe shares this one multiplier. Layer 2 — physics behavior: this is Wave Interference's and Double-Slit's primary knob — raising it stretches every Frame's transverse oscillation period, widening fringe/interference spacing without changing any Frame's mass or capacity (see docs/internal/records/physics-lab/2026-06-16-wave-interference-wavelengthScale.md, docs/internal/physics-lab/double-slit-wavelength.md for the observed sweep figures)."}]},DimensionDescriptor:{kind:"Dimension",description:'A scale layer in the simulation (a "dimension" in FRQTL terminology). Each dimension is a spatial index (QuadTree) that organises frames at one scale. Properties are readonly — the engine manages dimensional structure. THROW-OR-APPLY: any write attempt FAIL-LOUDs with TypeError.',fields:[{name:"layer",type:"readonly",engineVisible:!0,description:"Dimension layer index (u32). Assigned at creation (add_dimension / addDimension). 0 = fundamental (leaf-quanta layer). Higher values = higher scales. Engine-owned — write THROWS (topology is engine-derived)."},{name:"frame_count",type:"readonly",engineVisible:!0,description:"Number of frames currently in this dimension (usize). Changes each tick as frames are added, promoted, or GC'd. Derived from the dimension's frame list length — not user-writable."}]}};"undefined"!=typeof module&&module.exports?module.exports=EngineScopeDescriptors:"undefined"!=typeof window&&(window.EngineScopeDescriptors=EngineScopeDescriptors)}();